CREATE VIRTUAL TABLE t2 USING fts4;
CREATE TABLE input(doc TEXT NOT NULL);
WITH RECURSIVE n(x) AS (VALUES(0) UNION ALL SELECT x+1 FROM n WHERE x<999), b(s) AS (SELECT group_concat(token,' ') FROM (SELECT char(97+(x/100),97+((x/10)%10),97+(x%10)) AS token FROM n ORDER BY x)), r(i,s,base) AS (SELECT 1,s,s FROM b UNION ALL SELECT i+1,s||base,base FROM r WHERE i<10) INSERT INTO input SELECT s FROM r WHERE i=10;
CREATE TABLE a(x INTEGER);
INSERT INTO a VALUES(0);
CREATE TRIGGER au AFTER UPDATE ON a BEGIN INSERT INTO t2 SELECT doc FROM input; INSERT INTO t2 SELECT doc FROM input; INSERT INTO t2 SELECT doc FROM input; INSERT INTO t2 SELECT doc FROM input; INSERT INTO t2 SELECT doc FROM input; END;
